// EduFlow SW-06 — Audit Logging
// Handles both Sub-Workflow calls & Webhook POST calls

const items = $input.all();

function isUuid(value) {
  return typeof value === 'string' &&
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value);
}

return items.map((item, index) => {
  const raw = item.json ?? {};
  const input = (raw.body && typeof raw.body === 'object') ? { ...raw, ...raw.body } : raw;

  const action = String(input.action ?? '').trim();
  const entityType = String(input.entity_type ?? '').trim();

  if (!action) {
    throw new Error(`Audit item ${index + 1}: "action" is required.`);
  }
  if (!entityType) {
    throw new Error(`Audit item ${index + 1}: "entity_type" is required.`);
  }
  if (action.length > 120) {
    throw new Error(`Audit item ${index + 1}: "action" must be 120 characters or fewer.`);
  }
  if (entityType.length > 80) {
    throw new Error(`Audit item ${index + 1}: "entity_type" must be 80 characters or fewer.`);
  }

  const asJsonObject = (value, fieldName) => {
    if (value === undefined || value === null) return null;
    if (typeof value !== 'object' || Array.isArray(value)) {
      throw new Error(`Audit item ${index + 1}: "${fieldName}" must be an object or null.`);
    }
    return value;
  };

  const detailsObj = asJsonObject(input.details, 'details') ?? {};

  // Normalize workspace_id, actor_id, entity_id to UUID or null (safe for Postgres UUID columns)
  let cleanWorkspaceId = null;
  if (input.workspace_id) {
    if (isUuid(input.workspace_id)) cleanWorkspaceId = input.workspace_id;
    else detailsObj.original_workspace_id = String(input.workspace_id);
  }

  let cleanActorId = null;
  if (input.actor_id) {
    if (isUuid(input.actor_id)) cleanActorId = input.actor_id;
    else detailsObj.original_actor_id = String(input.actor_id);
  }

  let cleanEntityId = null;
  if (input.entity_id) {
    if (isUuid(input.entity_id)) cleanEntityId = input.entity_id;
    else detailsObj.original_entity_id = String(input.entity_id);
  }

  return {
    json: {
      workspace_id: cleanWorkspaceId,
      actor_id: cleanActorId,
      actor_role: input.actor_role ? String(input.actor_role).trim() : null,
      action,
      entity_type: entityType,
      entity_id: cleanEntityId,
      source: input.source ? String(input.source).trim().slice(0, 120) : 'n8n',
      details: detailsObj,
      before_data: asJsonObject(input.before_data, 'before_data'),
      after_data: asJsonObject(input.after_data, 'after_data')
    }
  };
});

// EduFlow Notifications Hub - fan out and persist each notification row.
const raw = $input.first().json;
const b = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
const isUuid = (v) => typeof v === 'string' &&
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v);

const title = b.title || 'EduFlow Notification';
const message = b.message || '';
const ntype = b.notification_type || 'general';
const related = b.related_url || null;
const userIds = Array.isArray(b.user_ids) ? b.user_ids.filter(isUuid) : [];

if (userIds.length === 0) {
  // Keep one item flowing so the HTTP node always produces output.
  return [{ json: { _skip: true, reason: 'no valid UUID user_ids' } }];
}

return userIds.map((uid) => ({ json: {
  _skip: false,
  _body: JSON.stringify({
    user_id: uid,
    title,
    message,
    notification_type: ntype,
    related_url: related,
    is_read: false,
  })
} }));

// EduFlow Exams & Assessment Hub - server-side start/submit/grading against Supabase.
// Runs inside the n8n Code node "CODE - Exams Hub" (Run Once for All Items).
const raw = $input.first().json;
const b = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
const action = String(b.action || '').trim();

const BASE = 'https://zhbntxnsdznpdqmjyxpp.supabase.co/rest/v1';
const SERVICE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InpoYm50eG5zZHpucGRxbWp5eHBwIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc5MzkzMDY2NCwiZXhwIjoyMTA5NTA2NjY0fQ.6HLb01zQpGGwn6Hp_HGt3MlMhl8M5i9wXMqxWEgUdwA';

const isUuid = (v) => typeof v === 'string' &&
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v);

const respond = (obj) => [{ json: obj }];
const fail = (message) => respond({ success: false, error: message });

// Code node HTTP helper (this.helpers in new Code node, $helpers as fallback).
const helpersRef = (typeof this !== 'undefined' && this && this.helpers) ||
  (typeof $helpers !== 'undefined' ? $helpers : null);
if (!helpersRef || !helpersRef.httpRequest) {
  return respond({ success: false, error: 'httpRequest helper is not available in this n8n Code node.' });
}

async function dbRequest(method, path, body, prefer) {
  const headers = {
    apikey: SERVICE_KEY,
    Authorization: 'Bearer ' + SERVICE_KEY,
    'Content-Type': 'application/json',
  };
  if (prefer) headers.Prefer = prefer;
  const opts = { method, url: BASE + path, headers, json: true };
  if (body !== undefined && body !== null) opts.body = body;
  try {
    return { ok: true, data: await helpersRef.httpRequest(opts) };
  } catch (err) {
    const msg = (err && err.response && err.response.body && err.response.body.message)
      || (err && err.message) || 'Supabase request failed';
    return { ok: false, error: msg };
  }
}

async function getExam(examId) {
  const r = await dbRequest('GET', '/exams?id=eq.' + examId +
    '&select=id,session_id,title,passing_score,duration_minutes,is_published');
  if (!r.ok) return { error: r.error };
  const row = Array.isArray(r.data) ? r.data[0] : r.data;
  if (!row) return { error: 'Exam not found' };
  return { exam: row };
}

async function getQuestions(examId, withAnswers) {
  const cols = withAnswers
    ? 'id,question_text,question_type,options,points,correct_answer,explanation'
    : 'id,question_text,question_type,options,points';
  const r = await dbRequest('GET', '/questions?exam_id=eq.' + examId +
    '&select=' + cols + '&order=created_at.asc');
  if (!r.ok) return { error: r.error };
  return { questions: Array.isArray(r.data) ? r.data : [] };
}

// ---------------- exam.create_draft / exam.create ----------------
if (action === 'exam.create_draft' || action === 'exam.create') {
  if (!isUuid(b.session_id)) return fail('session_id (UUID) is required to create an exam.');
  const examRow = {
    session_id: b.session_id,
    title: b.title || 'اختبار EduFlow',
    passing_score: typeof b.passing_score === 'number' ? b.passing_score : 70,
    duration_minutes: b.duration_minutes || 15,
    is_published: b.is_published !== undefined ? !!b.is_published : true,
  };
  if (isUuid(b.id)) examRow.id = b.id;
  for (const k of ['subject', 'grade_level', 'deadline', 'creator_role', 'creation_mode', 'curriculum_type', 'material_url']) {
    if (b[k] !== undefined && b[k] !== null) examRow[k] = b[k];
  }
  const exRes = await dbRequest('POST', '/exams', examRow, 'resolution=merge-duplicates,return=representation');
  if (!exRes.ok) return fail('Could not save exam: ' + exRes.error);
  const examRowOut = Array.isArray(exRes.data) ? exRes.data[0] : exRes.data;
  const examId = (examRowOut && examRowOut.id) || examRow.id;

  let questionsSaved = 0;
  if (Array.isArray(b.questions) && b.questions.length > 0 && examId) {
    const qRows = b.questions
      .filter((q) => q && q.question_text)
      .map((q) => {
        const row = {
          exam_id: examId,
          question_text: q.question_text,
          question_type: q.question_type === 'true_false' ? 'true_false' : 'mcq',
          options: Array.isArray(q.options) ? q.options : [],
          correct_answer: q.correct_answer != null ? String(q.correct_answer) : '',
          points: typeof q.points === 'number' ? q.points : 1,
        };
        if (isUuid(q.id)) row.id = q.id;
        row.explanation = q.explanation || null;
        return row;
      });
    if (qRows.length > 0) {
      const qRes = await dbRequest('POST', '/questions', qRows, 'resolution=merge-duplicates,return=representation');
      if (!qRes.ok) return fail('Exam saved but questions failed: ' + qRes.error);
      questionsSaved = Array.isArray(qRes.data) ? qRes.data.length : qRows.length;
    }
  }
  return respond({ success: true, action: 'exam.create_draft', exam_id: examId, questions_saved: questionsSaved });
}

// ---------------- exam.publish ----------------
if (action === 'exam.publish') {
  if (!isUuid(b.exam_id)) return fail('exam_id (UUID) is required to publish an exam.');
  const r = await dbRequest('PATCH', '/exams?id=eq.' + b.exam_id, { is_published: true }, 'return=representation');
  if (!r.ok) return fail('Could not publish exam: ' + r.error);
  return respond({ success: true, action: 'exam.publish', exam_id: b.exam_id });
}

// ---------------- exam.start_attempt ----------------
if (action === 'exam.start_attempt') {
  if (!isUuid(b.exam_id) || !isUuid(b.student_id)) return fail('exam_id and student_id (UUID) are required.');
  const g = await getExam(b.exam_id);
  if (g.error) return fail(g.error);
  if (g.exam.is_published !== true) return fail('Exam is not published');

  const q = await getQuestions(b.exam_id, false);
  if (q.error) return fail(q.error);
  if (q.questions.length === 0) return fail('Exam has no questions');

  const totalScore = q.questions.reduce((s, x) => s + (Number(x.points) || 0), 0);
  const aRes = await dbRequest('POST', '/exam_attempts', {
    exam_id: b.exam_id,
    student_id: b.student_id,
    started_at: new Date().toISOString(),
    score: 0,
    total_score: totalScore,
    passed: false,
  }, 'return=representation');
  if (!aRes.ok) return fail('Could not start attempt: ' + aRes.error);
  const attemptRow = Array.isArray(aRes.data) ? aRes.data[0] : aRes.data;

  return respond({
    success: true,
    action: 'exam.start_attempt',
    attempt_id: attemptRow && attemptRow.id,
    exam: {
      id: g.exam.id,
      title: g.exam.title,
      duration_minutes: g.exam.duration_minutes,
      passing_score: g.exam.passing_score != null ? g.exam.passing_score : 70,
      total_score: totalScore,
    },
    questions: q.questions,
  });
}

// ---------------- exam.submit_attempt ----------------
if (action === 'exam.submit_attempt') {
  if (!isUuid(b.exam_id) || !isUuid(b.student_id)) return fail('exam_id and student_id (UUID) are required.');
  const now = new Date().toISOString();

  // Legacy mode: browser already computed the score (kept for backwards compatibility).
  if (b.answers === undefined || b.answers === null) {
    const score = typeof b.score === 'number' ? b.score : (parseFloat(b.score) || 0);
    const total = typeof b.total_score === 'number' ? b.total_score : (parseFloat(b.total_score) || 0);
    const pct = total > 0 ? (score / total) * 100 : 0;
    const body = {
      exam_id: b.exam_id,
      student_id: b.student_id,
      score,
      started_at: b.started_at || now,
      submitted_at: b.submitted_at || now,
      passed: b.passed !== undefined ? !!b.passed : (total > 0 ? pct >= 70 : score >= 70),
    };
    if (total > 0) body.total_score = total;
    const w = await dbRequest('POST', '/exam_attempts', body, 'return=representation');
    if (!w.ok) return fail('Could not save attempt: ' + w.error);
    const row = Array.isArray(w.data) ? w.data[0] : w.data;
    return respond({ success: true, action: 'exam.submit_attempt', mode: 'legacy', attempt_id: row && row.id, score, total_score: total });
  }

  // Server-side grading mode.
  const g = await getExam(b.exam_id);
  if (g.error) return fail(g.error);
  const passingScore = g.exam.passing_score != null ? Number(g.exam.passing_score) : 70;

  const q = await getQuestions(b.exam_id, true);
  if (q.error) return fail(q.error);
  if (q.questions.length === 0) return fail('Exam has no questions');

  const answers = (b.answers && typeof b.answers === 'object') ? b.answers : {};
  let score = 0;
  const review = [];
  for (const qu of q.questions) {
    const studentAns = answers[qu.id] != null ? String(answers[qu.id]) : '';
    const correct = String(qu.correct_answer || '');
    const isCorrect = studentAns.trim() === correct.trim();
    const pts = Number(qu.points) || 0;
    if (isCorrect) score += pts;
    review.push({
      question: qu.question_text,
      studentChoice: studentAns || 'لم يتم الحل',
      correctChoice: correct,
      isCorrect,
      explanation: qu.explanation || 'الإجابة النموذجية تعتمد على المفاهيم العلمية المقررة.',
    });
  }
  const total = q.questions.reduce((s, x) => s + (Number(x.points) || 0), 0) || 1;
  const pct = Math.round((score / total) * 100);
  const passed = pct >= passingScore;

  let attemptId = isUuid(b.attempt_id) ? b.attempt_id : null;
  const writeBody = { score, total_score: total, passed, submitted_at: now };
  let w;
  if (attemptId) {
    w = await dbRequest('PATCH', '/exam_attempts?id=eq.' + attemptId, writeBody, 'return=representation');
    if (w.ok) {
      const rows = Array.isArray(w.data) ? w.data : (w.data ? [w.data] : []);
      if (rows.length === 0) attemptId = null; // attempt row did not exist; insert instead
    }
  }
  if (!attemptId) {
    w = await dbRequest('POST', '/exam_attempts', {
      exam_id: b.exam_id,
      student_id: b.student_id,
      started_at: b.started_at || now,
      ...writeBody,
    }, 'return=representation');
  }
  if (!w.ok) return fail('Could not save attempt: ' + w.error);
  const saved = Array.isArray(w.data) ? w.data[0] : w.data;

  return respond({
    success: true,
    action: 'exam.submit_attempt',
    mode: 'server_graded',
    attempt_id: (saved && saved.id) || attemptId,
    score,
    total,
    pct,
    passed,
    passing_score: passingScore,
    exam_title: g.exam.title,
    review,
  });
}

return fail('Unsupported action: ' + action);

const req = $('CODE – Process Notification').first().json;
if (req && req._skip) {
  return [{ json: { success: true, workflow: 'NOTIFICATIONS-HUB', inserted: 0, skipped: true, reason: req.reason || 'no recipients' } }];
}
const rows = $input.all().map(i => i.json).filter(j => j && !j.error);
return [{ json: {
  success: true,
  workflow: 'NOTIFICATIONS-HUB',
  inserted: rows.length,
  persisted: true,
  timestamp: new Date().toISOString()
} }];

// EduFlow Payments & Earnings Hub - server-side payments, waivers, invoices and teacher earnings.
// Runs inside the n8n Code node "CODE - Payments Hub" (Run Once for All Items).
// Mirrors the Supabase functions record_student_payment / admin_waive_student_payment /
// admin_generate_group_invoices / admin_generate_session_earning / admin_refresh_overdue_payments,
// but works without a Supabase Auth session (the demo login is local), same as the Exams Hub.
const raw = $input.first().json;
const b = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
const action = String(b.action || '').trim();

const BASE = 'https://zhbntxnsdznpdqmjyxpp.supabase.co/rest/v1';
const SERVICE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InpoYm50eG5zZHpucGRxbWp5eHBwIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc5MzkzMDY2NCwiZXhwIjoyMTA5NTA2NjY0fQ.6HLb01zQpGGwn6Hp_HGt3MlMhl8M5i9wXMqxWEgUdwA';

const isUuid = (v) => typeof v === 'string' &&
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v);

const respond = (obj) => [{ json: obj }];
const fail = (message) => respond({ success: false, error: message });

const METHODS = ['cash', 'instapay', 'vodafone_cash', 'bank_transfer', 'other'];

// Code node HTTP helper (this.helpers in new Code node, $helpers as fallback).
const helpersRef = (typeof this !== 'undefined' && this && this.helpers) ||
  (typeof $helpers !== 'undefined' ? $helpers : null);
if (!helpersRef || !helpersRef.httpRequest) {
  return respond({ success: false, error: 'httpRequest helper is not available in this n8n Code node.' });
}

async function dbRequest(method, path, body, prefer) {
  const headers = {
    apikey: SERVICE_KEY,
    Authorization: 'Bearer ' + SERVICE_KEY,
    'Content-Type': 'application/json',
  };
  if (prefer) headers.Prefer = prefer;
  const opts = { method, url: BASE + path, headers, json: true };
  if (body !== undefined && body !== null) opts.body = body;
  try {
    return { ok: true, data: await helpersRef.httpRequest(opts) };
  } catch (err) {
    const msg = (err && err.response && err.response.body && err.response.body.message)
      || (err && err.message) || 'Supabase request failed';
    return { ok: false, error: msg };
  }
}

async function getPayment(paymentId) {
  const r = await dbRequest('GET', '/student_payments?id=eq.' + paymentId +
    '&select=id,student_id,group_id,session_id,amount,currency,period_label,due_date,status,paid_amount');
  if (!r.ok) return { error: r.error };
  const row = Array.isArray(r.data) ? r.data[0] : r.data;
  if (!row) return { error: 'الفاتورة غير موجودة على السيرفر' };
  return { payment: row };
}

async function sumTransactions(paymentId) {
  const r = await dbRequest('GET', '/payment_transactions?student_payment_id=eq.' + paymentId + '&select=amount');
  if (!r.ok) return { error: r.error };
  const rows = Array.isArray(r.data) ? r.data : [];
  return { paid: rows.reduce((s, t) => s + (Number(t.amount) || 0), 0) };
}

// recorded_by must reference a profiles row (or be NULL after setup4.sql).
// The demo admin/assistant accounts are local-only (adm-1 / ast-1), so resolve
// a real UUID when possible: a passed UUID, else the first staff profile in DB.
async function resolveRecorder(val) {
  if (isUuid(val)) return val;
  const r = await dbRequest('GET', '/profiles?role=in.(admin,assistant)&select=id&limit=1');
  if (r.ok && Array.isArray(r.data) && r.data.length > 0 && isUuid(r.data[0].id)) return r.data[0].id;
  return null;
}

// ---------------- payment.record (admin record + assistant voucher) ----------------
if (action === 'payment.record') {
  if (!isUuid(b.payment_id)) return fail('payment_id (UUID) is required.');
  const amount = Number(b.amount);
  if (!amount || amount <= 0) return fail('Payment amount must be greater than zero.');
  if (!METHODS.includes(b.payment_method)) return fail('Invalid payment method.');

  const g = await getPayment(b.payment_id);
  if (g.error) return fail(g.error);
  const p = g.payment;
  if (p.status === 'waived') return fail('لا يمكن تحصيل فاتورة معفاة');
  if (p.status === 'paid') return fail('الفاتورة مسددة بالكامل بالفعل');

  const s = await sumTransactions(b.payment_id);
  if (s.error) return fail(s.error);
  const total = Number(p.amount) || 0;
  const paidSoFar = s.paid;
  const remainingBefore = total - paidSoFar;
  if (remainingBefore <= 0) return fail('No remaining balance for this payment.');
  if (amount > remainingBefore) {
    return fail('Payment exceeds remaining balance: ' + remainingBefore);
  }

  const recorder = await resolveRecorder(b.recorded_by);
  const ref = b.reference_number ? String(b.reference_number).trim() : '';
  let notes = b.notes ? String(b.notes) : '';
  if (b.recorder_name) notes = (notes ? notes + ' ' : '') + '(رصد: ' + String(b.recorder_name) + ')';

  const txRow = {
    student_payment_id: b.payment_id,
    amount,
    payment_method: b.payment_method,
    paid_at: new Date().toISOString(),
    notes: notes || null,
  };
  if (recorder) txRow.recorded_by = recorder;

  // Try with the reference_number column first (exists after setup4.sql);
  // on older schemas retry without it and keep the number inside notes.
  let txRes;
  if (ref) {
    txRes = await dbRequest('POST', '/payment_transactions', { ...txRow, reference_number: ref }, 'return=representation');
    if (!txRes.ok && /reference_number/i.test(txRes.error || '')) {
      txRow.notes = ((notes ? notes + ' ' : '') + 'رقم الإيصال: ' + ref) || null;
      txRes = await dbRequest('POST', '/payment_transactions', txRow, 'return=representation');
    }
  } else {
    txRes = await dbRequest('POST', '/payment_transactions', txRow, 'return=representation');
  }
  if (!txRes.ok) {
    if (/recorded_by/i.test(txRes.error || '') && !recorder) {
      return fail('قاعدة البيانات ترفض عملية بدون مسجّل (recorded_by). نفّذ ملف setup4.sql في Supabase SQL Editor أولاً.');
    }
    return fail('Could not record transaction: ' + txRes.error);
  }
  const txOut = Array.isArray(txRes.data) ? txRes.data[0] : txRes.data;

  const newPaid = paidSoFar + amount;
  const newRemaining = total - newPaid;
  const newStatus = newRemaining <= 0 ? 'paid' : 'partially_paid';

  const updateRow = {
    status: newStatus,
    payment_method: b.payment_method,
    paid_at: newStatus === 'paid' ? new Date().toISOString() : null,
    paid_amount: newPaid,
  };
  if (recorder) updateRow.recorded_by = recorder;
  let upRes = await dbRequest('PATCH', '/student_payments?id=eq.' + b.payment_id, updateRow, 'return=representation');
  if (!upRes.ok && /paid_amount/i.test(upRes.error || '')) {
    delete updateRow.paid_amount;
    upRes = await dbRequest('PATCH', '/student_payments?id=eq.' + b.payment_id, updateRow, 'return=representation');
  }
  if (!upRes.ok) return fail('Transaction saved but invoice update failed: ' + upRes.error);

  return respond({
    success: true,
    mode: 'server_recorded',
    action: 'payment.record',
    transaction_id: txOut && txOut.id,
    reference_number: ref || null,
    total_amount: total,
    paid_amount: newPaid,
    remaining_amount: Math.max(0, newRemaining),
    status: newStatus,
  });
}

// ---------------- payment.waive ----------------
if (action === 'payment.waive') {
  if (!isUuid(b.payment_id)) return fail('payment_id (UUID) is required.');
  const reason = b.reason ? String(b.reason).trim() : '';
  if (!reason) return fail('سبب الإعفاء مطلوب إلزامياً');

  const g = await getPayment(b.payment_id);
  if (g.error) return fail(g.error);
  if (!['unpaid', 'overdue', 'partially_paid'].includes(g.payment.status)) {
    return fail('لا يمكن إعفاء فاتورة بحالة ' + g.payment.status);
  }

  const waver = await resolveRecorder(b.waived_by);
  const waiveRow = {
    status: 'waived',
    waived_reason: reason,
    waived_at: new Date().toISOString(),
  };
  if (waver) waiveRow.waived_by = waver;
  const r = await dbRequest('PATCH', '/student_payments?id=eq.' + b.payment_id, waiveRow, 'return=representation');
  if (!r.ok) return fail('Could not waive payment: ' + r.error);
  return respond({ success: true, action: 'payment.waive', payment_id: b.payment_id, status: 'waived' });
}

// ---------------- invoice.create (mirror of a locally created invoice) ----------------
if (action === 'invoice.create') {
  if (!isUuid(b.student_id) || !isUuid(b.group_id)) return fail('student_id and group_id (UUID) are required.');
  const amount = Number(b.amount);
  if (!(amount >= 0)) return fail('amount is required.');
  const row = {
    student_id: b.student_id,
    group_id: b.group_id,
    amount,
    currency: b.currency || 'EGP',
    status: 'unpaid',
  };
  if (isUuid(b.id)) row.id = b.id;
  if (isUuid(b.session_id)) row.session_id = b.session_id;
  if (b.period_label) row.period_label = String(b.period_label);
  if (b.due_date) row.due_date = String(b.due_date);
  const r = await dbRequest('POST', '/student_payments', row, 'resolution=merge-duplicates,return=representation');
  if (!r.ok) return fail('Could not create invoice: ' + r.error);
  const out = Array.isArray(r.data) ? r.data[0] : r.data;
  return respond({ success: true, action: 'invoice.create', payment_id: out && out.id });
}

// ---------------- invoices.generate_group (monthly / per_session) ----------------
if (action === 'invoices.generate_group') {
  if (!isUuid(b.group_id)) return fail('group_id (UUID) is required.');
  const bs = await dbRequest('GET', '/group_billing_settings?group_id=eq.' + b.group_id +
    '&select=payment_type,amount,currency');
  if (!bs.ok) return fail(bs.error);
  const billing = Array.isArray(bs.data) ? bs.data[0] : bs.data;
  if (!billing) return fail('Group billing settings not found.');

  const en = await dbRequest('GET', '/enrollments?group_id=eq.' + b.group_id +
    '&status=eq.active&select=student_id');
  if (!en.ok) return fail(en.error);
  const studentIds = (Array.isArray(en.data) ? en.data : []).map((e) => e.student_id).filter(isUuid);
  if (studentIds.length === 0) return fail('No active students in this group.');

  let sessionId = null;
  let periodLabel = b.period_label ? String(b.period_label).trim() : '';
  if (billing.payment_type === 'per_session') {
    if (!isUuid(b.session_id)) return fail('A session ID is required for per-session billing.');
    const sr = await dbRequest('GET', '/sessions?id=eq.' + b.session_id + '&select=id,group_id,session_number');
    if (!sr.ok) return fail(sr.error);
    const sess = Array.isArray(sr.data) ? sr.data[0] : sr.data;
    if (!sess || sess.group_id !== b.group_id) return fail('Session does not belong to this group.');
    sessionId = b.session_id;
    periodLabel = 'Session ' + (sess.session_number != null ? sess.session_number : '');
  } else {
    if (!periodLabel) return fail('Period label is required.');
  }

  // Existing invoices for this group + period/session (dedupe + waived guard)
  let existQuery = '/student_payments?group_id=eq.' + b.group_id + '&select=student_id,status';
  if (sessionId) existQuery += '&session_id=eq.' + sessionId;
  else existQuery += '&period_label=eq.' + encodeURIComponent(periodLabel);
  const ex = await dbRequest('GET', existQuery);
  if (!ex.ok) return fail(ex.error);
  const existing = Array.isArray(ex.data) ? ex.data : [];
  if (sessionId && existing.some((x) => x.status === 'waived')) {
    return fail('A waived invoice already exists for this session.');
  }
  const already = new Set(existing.map((x) => x.student_id));

  if (!b.due_date) return fail('due_date is required.');
  const rows = studentIds
    .filter((sid) => !already.has(sid))
    .map((sid) => ({
      student_id: sid,
      group_id: b.group_id,
      session_id: sessionId,
      amount: Number(billing.amount) || 0,
      currency: billing.currency || 'EGP',
      period_label: periodLabel,
      due_date: String(b.due_date),
      status: 'unpaid',
    }));
  if (rows.length === 0) {
    return respond({ success: true, action: 'invoices.generate_group', created_invoices: 0, payment_type: billing.payment_type, period_label: periodLabel });
  }
  const ins = await dbRequest('POST', '/student_payments', rows, 'return=representation');
  if (!ins.ok) return fail('Could not generate invoices: ' + ins.error);
  return respond({
    success: true,
    action: 'invoices.generate_group',
    created_invoices: Array.isArray(ins.data) ? ins.data.length : rows.length,
    payment_type: billing.payment_type,
    period_label: periodLabel,
    session_id: sessionId,
  });
}

// ---------------- earning.generate_session ----------------
if (action === 'earning.generate_session') {
  if (!isUuid(b.session_id)) return fail('session_id (UUID) is required.');
  const sr = await dbRequest('GET', '/sessions?id=eq.' + b.session_id + '&select=id,group_id,title');
  if (!sr.ok) return fail(sr.error);
  const sess = Array.isArray(sr.data) ? sr.data[0] : sr.data;
  if (!sess) return fail('Session not found.');

  const gr = await dbRequest('GET', '/course_groups?id=eq.' + sess.group_id + '&select=id,teacher_id,name');
  if (!gr.ok) return fail(gr.error);
  const grp = Array.isArray(gr.data) ? gr.data[0] : gr.data;
  if (!grp) return fail('Group not found.');

  const cr = await dbRequest('GET', '/teacher_compensation?group_id=eq.' + sess.group_id +
    '&teacher_id=eq.' + grp.teacher_id + '&select=compensation_type,amount,currency');
  if (!cr.ok) return fail(cr.error);
  const comp = Array.isArray(cr.data) ? cr.data[0] : cr.data;
  if (!comp) return fail('Teacher compensation settings not found.');
  if (comp.compensation_type !== 'per_session') {
    return fail('This function only processes per-session compensation.');
  }

  const dup = await dbRequest('GET', '/teacher_earnings?session_id=eq.' + b.session_id + '&select=id,status');
  if (!dup.ok) return fail(dup.error);
  if (Array.isArray(dup.data) && dup.data.length > 0) {
    return respond({ success: true, action: 'earning.generate_session', created: false, earning_id: dup.data[0].id });
  }

  const ins = await dbRequest('POST', '/teacher_earnings', {
    teacher_id: grp.teacher_id,
    group_id: sess.group_id,
    session_id: b.session_id,
    amount: Number(comp.amount) || 0,
    currency: comp.currency || 'EGP',
    description: 'مستحقات حصة: ' + (sess.title || ''),
    status: 'pending',
  }, 'return=representation');
  if (!ins.ok) return fail('Could not create earning: ' + ins.error);
  const out = Array.isArray(ins.data) ? ins.data[0] : ins.data;
  return respond({
    success: true,
    action: 'earning.generate_session',
    created: true,
    earning_id: out && out.id,
    teacher_id: grp.teacher_id,
    amount: Number(comp.amount) || 0,
    currency: comp.currency || 'EGP',
  });
}

// ---------------- earning.approve / earning.pay ----------------
if (action === 'earning.approve' || action === 'earning.pay') {
  if (!isUuid(b.earning_id)) return fail('earning_id (UUID) is required.');
  if (action === 'earning.approve') {
    const r = await dbRequest('PATCH', '/teacher_earnings?id=eq.' + b.earning_id + '&status=eq.pending',
      { status: 'approved' }, 'return=representation');
    if (!r.ok) return fail('Could not approve earning: ' + r.error);
    if (!Array.isArray(r.data) || r.data.length === 0) return fail('المستحق غير موجود أو ليس معلقاً');
    return respond({ success: true, action, earning_id: b.earning_id, status: 'approved' });
  }
  const r = await dbRequest('PATCH', '/teacher_earnings?id=eq.' + b.earning_id + '&status=in.(pending,approved)',
    { status: 'paid', paid_at: new Date().toISOString() }, 'return=representation');
  if (!r.ok) return fail('Could not pay earning: ' + r.error);
  if (!Array.isArray(r.data) || r.data.length === 0) return fail('المستحق غير موجود أو تم صرفه بالفعل');
  return respond({ success: true, action, earning_id: b.earning_id, status: 'paid' });
}

// ---------------- payments.refresh_overdue ----------------
if (action === 'payments.refresh_overdue') {
  const today = new Date().toISOString().slice(0, 10);
  const r = await dbRequest('PATCH',
    '/student_payments?status=in.(unpaid,partially_paid)&due_date=lt.' + today,
    { status: 'overdue' }, 'return=representation');
  if (!r.ok) return fail('Could not refresh overdue payments: ' + r.error);
  const count = Array.isArray(r.data) ? r.data.length : 0;
  return respond({ success: true, action: 'payments.refresh_overdue', updated: count });
}

return fail('Unknown action: ' + (action || '(none)') + '. Expected one of: payment.record, payment.waive, invoice.create, invoices.generate_group, earning.generate_session, earning.approve, earning.pay, payments.refresh_overdue.');
